-- Benchmarks researched 2026-11-03; QSMind Riyadh source rates. Single observed prices; VAT status not stated.
on conflict(code) do update set category=excluded.category,name=excluded.name,spec=excluded.spec,unit=excluded.unit,material_cost=excluded.material_cost,labor_cost=excluded.labor_cost,equipment_cost=excluded.equipment_cost,market_low=excluded.market_low,market_fair=excluded.market_fair,market_high=excluded.market_high,source=excluded.source,checked_at=excluded.checked_at,is_active=true;
-- Researched Riyadh material prices; source pages and checked dates stored per item. VAT-inclusive published prices divided by 1.15 where indicated in specs.
on conflict(code) do update set category=excluded.category,name=excluded.name,spec=excluded.spec,unit=excluded.unit,material_cost=excluded.material_cost,labor_cost=excluded.labor_cost,equipment_cost=excluded.equipment_cost,market_low=excluded.market_low,market_fair=excluded.market_fair,market_high=excluded.market_high,source=excluded.source,checked_at=excluded.checked_at,is_active=true;
update public.price_catalog set is_active=false where code='CONC-SLAB';
update public.price_catalog set steel_kg_per_unit=25,steel_included_default=true where code='RC-SLAB';
update public.price_catalog set steel_kg_per_unit=25 where code='RC-SLAB-NO-STEEL';
update public.price_catalog set steel_included_default=true where steel_kg_per_unit>0 and code<>'RC-SLAB-NO-STEEL';
update public.price_catalog set steel_kg_per_unit=25,steel_included_default=true where code='CONC-SLAB';


